; Gods: the Amiga-specific routines, generated by scripts/gen_amiga_asm.py from the original's resident code.
; The instruction sequences are the original's (the intro's timing depends on how long they take); the C calling
; convention (arguments on the stack, d2-d7/a2-a6 preserved) is added around them.
        xref _display, _screen_front, _screen_back, _draw_flag, _blank_plane
        xdef _blitter_wait, _blit_copy, _blit_copy_right, _screen_clear, _screen_restore, _plane5_set, _plane5_clear
        xdef _blit_image, _blit_image_wide, _delay, _startup_delay
        section .text,code

; orig $002F1E: wait until the blitter has finished (and give it priority while waiting)
_blitter_wait:
        move.w #$8400,$dff096.l
w2f26:
        btst.b #$e,$dff002.l
        bne.b w2f26
        move.w #$400,$dff096.l
        rts
blitter_wait = _blitter_wait

; void blit_copy(const void *src, void *dst), orig $001B7C: copy the 20 x 800 words at src to dst, A -> D
_blit_copy:
        move.l a6,-(sp)
        movea.l 8(sp),a0
        movea.l 12(sp),a1
        lea.l $dff000.l,a6
        bsr.w blitter_wait
        move.w #$ffff,$44(a6)
        move.w #$ffff,$46(a6)
        move.l a1,$54(a6)
        move.l a0,$50(a6)
        move.w #$0,$66(a6)
        move.w #$0,$64(a6)
        move.w #$0,$42(a6)
        move.w #$9f0,$40(a6)
        move.w #$400,$96(a6)
        move.w #$c814,$58(a6)
        move.w #$8400,$96(a6)
        movea.l (sp)+,a6
        rts

; void blit_copy_right(const void *src, void *dst), orig $001BC6: only the right-hand 9 words of each row
_blit_copy_right:
        move.l a6,-(sp)
        movea.l 8(sp),a0
        movea.l 12(sp),a1
        lea.l $16(a0),a0
        lea.l $16(a1),a1
        lea.l $dff000.l,a6
        bsr.w blitter_wait
        move.w #$ffff,$44(a6)
        move.w #$ffff,$46(a6)
        move.l a1,$54(a6)
        move.l a0,$50(a6)
        move.w #$16,$66(a6)
        move.w #$16,$64(a6)
        move.w #$0,$42(a6)
        move.w #$9f0,$40(a6)
        move.w #$400,$96(a6)
        move.w #$c809,$58(a6)
        move.w #$8400,$96(a6)
        movea.l (sp)+,a6
        rts

; void screen_restore(void), orig $0030EE: copy the back screen over the front screen
_screen_restore:
        movem.l d7/a0-a1,-(a7)
        movea.l (_screen_back).l,a0
        movea.l (_screen_front).l,a1
        move.w #$270f,d7
s3102:
        move.l (a0)+,(a1)+
        dbra d7,s3102
        movem.l (a7)+,d7/a0-a1
        rts

; void screen_clear(void), orig $0030D4: clear the front screen
_screen_clear:
        movem.l d7/a0,-(a7)
        movea.l (_screen_front).l,a0
        move.w #$270f,d7
z30e2:
        clr.l (a0)+
        dbra d7,z30e2
        movem.l (a7)+,d7/a0
        rts

; void plane5_set(void), orig $001D54: set the whole fifth bitplane of the front screen (d0/d1 for the original's d6/d7)
_plane5_set:
        movea.l (_screen_front).l,a0
        lea.l $7d00(a0),a0
        move.w #$c7,d1
        moveq #$ff,d0
p1d64:
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        dbra d1,p1d64
        rts

; void plane5_clear(void), orig $001D7E: clear the fifth bitplane of the front screen
_plane5_clear:
        movea.l (_screen_front).l,a0
        lea.l $7d00(a0),a0
        move.w #$c7,d1
        moveq #$0,d0
q1d8e:
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        move.l d0,(a0)+
        dbra d1,q1d8e
        rts

; void blit_image(uint8_t *dst, const uint8_t *src, uint16_t plane, uint16_t shift, uint16_t rows), orig $0032B6:
; draw an image one word wide (the planes are `plane` bytes apart) through a mask built from its planes
_blit_image:
        movem.l d2-d7/a2-a4,-(sp)
        movea.l 40(sp),a0          ; dst
        movea.l 44(sp),a1          ; src
        move.w 50(sp),d0           ; bytes between the planes
        move.w 54(sp),d1           ; pixel shift
        move.w 58(sp),d7           ; rows
        move.l #$ffff,d3
        clr.w (_display+$46).l
        moveq #$1,d6
        moveq #$0,d2
        move.b d1,d2
        bra.b i32de

